#define RING_MIN_CAP 16u

struct ring {
    uint8_t *buf;
    size_t cap;
    size_t head;
    size_t tail;
    int full;
};

static size_t next_index(size_t i, size_t cap)
{
    return (i + 1u) % cap;
}

struct ring *ring_new(size_t cap)
{
    struct ring *r;

    if (cap < RING_MIN_CAP) {
        cap = RING_MIN_CAP;
    }
    r = calloc(1, sizeof(*r));
    if (r == NULL) {
        return NULL;
    }
    r->buf = malloc(cap);
    if (r->buf == NULL) {
        free(r);
        return NULL;
    }
    r->cap = cap;
    return r;
}

void ring_free(struct ring *r)
{
    if (r == NULL) {
        return;
    }
    free(r->buf);
    free(r);
}

int ring_push(struct ring *r, uint8_t byte)
{
    if (r->full) {
        return -1;
    }
    r->buf[r->tail] = byte;
    r->tail = next_index(r->tail, r->cap);
    if (r->tail == r->head) {
        r->full = 1;
    }
    return 0;
}

int ring_pop(struct ring *r, uint8_t *out)
{
    if (!r->full && r->head == r->tail) {
        return -1;
    }
    *out = r->buf[r->head];
    r->head = next_index(r->head, r->cap);
    r->full = 0;
    return 0;
}

size_t ring_count(const struct ring *r)
{
    if (r->full) {
        return r->cap;
    }
    if (r->tail >= r->head) {
        return r->tail - r->head;
    }
    return r->cap - r->head + r->tail;
}

int ring_peek(const struct ring *r, size_t off, uint8_t *out)
{
    size_t idx;

    if (off >= ring_count(r)) {
        return -1;
    }
    idx = (r->head + off) % r->cap;
    *out = r->buf[idx];
    return 0;
}

int ring_write(struct ring *r, const void *data, size_t len)
{
    const uint8_t *p = data;
    size_t i;

    for (i = 0; i < len; i++) {
        if (ring_push(r, p[i]) != 0) {
            return -1;
        }
    }
    return 0;
}

void ring_clear(struct ring *r)
{
    r->head = 0;
    r->tail = 0;
    r->full = 0;
}

